"""Read saved ETH decision audits and full NAV hashes; no component execution."""
from common import *
rd=lambda p:json.loads(p.read_text());p=rd(R/'plan.json');r=rd(R/'report.json');before=sha(R/'report.json');sources={int(z['K']):z for z in p['read_only_references'].values() if z['scope']=='native' and z['asset']=='ETH' and z['role']=='component'};assert set(sources)=={5,6,7};arcs={V:json.loads(gzip.decompress((ROOT/z['archive']).read_bytes())) for V,z in sources.items()};rows=[]
for V,arc in sorted(arcs.items()):
 q=arc['spec']['parameters'];assert q['entry_volatility_window_days']==V and q['entry_volatility_ceiling']==.05625 and q['lookback_days']==5
 for k,s in arc['scenes'].items():
  ref=arcs[6]['scenes'][k];pairs=list(zip(s['decisions'],ref['decisions']));assert len(pairs)==391 and all(a['decision_index']==b['decision_index'] for a,b in pairs);sigs=sum(a['policy_audit']['observed_sample_logvol']!=b['policy_audit']['observed_sample_logvol'] for a,b in pairs);prefund=sum(a['policy_audit']['raw_desired_before_funding_filter']!=b['policy_audit']['raw_desired_before_funding_filter'] for a,b in pairs);wanted=sum(a['desired_direction']!=b['desired_direction'] for a,b in pairs);same=s['summary']['NAV_sha256_f64le']==ref['summary']['NAV_sha256_f64le'];assert same
  rows.append({'ETH_entry_volatility_window_days':V,'cost':int(k),'existing_native_fingerprint':sources[V]['fingerprint'],'actual_spec_entry_volatility_window_days':q['entry_volatility_window_days'],'different_saved_observed_sigma_days_to_V6':sigs,'different_saved_prefunding_desired_days_to_V6':prefund,'different_saved_final_desired_days_to_V6':wanted,'same_complete_NAV_to_V6':same,'executions':s['summary']['executions'],'cost_usdt':s['summary']['cost_usdt'],'funding_usdt':s['summary']['funding_usdt']})
assert all(z['different_saved_observed_sigma_days_to_V6']>0 for z in rows if z['ETH_entry_volatility_window_days']!=6);assert sha(R/'report.json')==before;put(R/'volatility_economic_review.json',{'passed':True,'recorded_utc':now(),'financial_report_sha256_unchanged':before,'rows':rows,'actual_parameter_changes_observed_in_saved_policy_sigma':True,'all_existing_ETH_source_complete_paths_same_as_V6':True,'definition_count_is_not_new_alpha_or_independent_trial_count':True,'no_financial_or_account_execution':True});print(json.dumps({'passed':True,'saved_scenes':len(rows),'policy_input_changes':sum(z['different_saved_observed_sigma_days_to_V6'] for z in rows),'prefunding_desired_differences':sum(z['different_saved_prefunding_desired_days_to_V6'] for z in rows),'final_desired_differences':sum(z['different_saved_final_desired_days_to_V6'] for z in rows),'new_model_executions':0}))
